create extension if not exists pgcrypto; create table if not exists public.issues(id uuid primary key default gen_random_uuid(),issue_number integer not null unique check(issue_number>0),title text not null,slug text not null unique,description text not null default '',publication_date date not null,cover_image_url text,pdf_url text,html_content text,departments text[] not null default '{}',status text not null default 'draft' check(status in('draft','scheduled','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table if not exists public.subscribers(id uuid primary key default gen_random_uuid(),email text not null unique,first_name text,subscription_status text not null default 'pending' check(subscription_status in('pending','active','unsubscribed','bounced')),confirmation_token_hash text,unsubscribe_token_hash text not null default encode(gen_random_bytes(32),'hex'),subscribed_at timestamptz not null default now(),confirmed_at timestamptz,unsubscribed_at timestamptz); create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(),issue_id uuid not null references public.issues(id) on delete restrict,subject text not null,status text not null default 'draft' check(status in('draft','queued','sending','completed','failed')),queued_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now()); create table if not exists public.email_deliveries(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete cascade,subscriber_id uuid not null references public.subscribers(id) on delete restrict,provider_message_id text,delivery_status text not null default 'queued' check(delivery_status in('queued','sent','delivered','bounced','failed')),sent_at timestamptz,error_message text,created_at timestamptz not null default now(),unique(campaign_id,subscriber_id)); create index if not exists issues_status_date_idx on public.issues(status,publication_date desc); create index if not exists subscribers_status_idx on public.subscribers(subscription_status); create index if not exists deliveries_campaign_status_idx on public.email_deliveries(campaign_id,delivery_status); alter table public.issues enable row level security; alter table public.subscribers enable row level security; alter table public.campaigns enable row level security; alter table public.email_deliveries enable row level security; create policy "Public can read published issues" on public.issues for select using(status='published'); -- Subscriber, campaign and delivery tables intentionally have no public policies; server-side service access only.